/// <summary>
/// class <c> MetTelemetryOrderProcessingStatusEvent </c> triggers custom event on order processing status change.
/// </summary>
public class MetTelemetryOrderProcessingStatusEvent
{
}

Method.Source:
/// <summary>
/// trigger custom event on order processing status change.
/// </summary>
/// <param name = "_salesTable"> instance of table <c> SalesTable </c></param>
/// <param name = "_metSalesTable"> instance of table <c> MetSalesTable </c></param>
public static void triggerOrderProcessingEvent(
    SalesTable      _salesTable, 
    METSalesTable   _metSalesTable)
{
    METSalesOrderProcessingStatus processingStatus = _metSalesTable.OrderProcessingStatus;

    switch (processingStatus)
    {
        case METSalesOrderProcessingStatus::ReadyForPricing:

            METTelemetrySOReadyForPricingEvent telemetryPricingEvent = METTelemetrySOReadyForPricingEvent::construct();
            telemetryPricingEvent.addRunTimePropertyToAppinsights(_salesTable, _metSalesTable);

            telemetryPricingEvent.processEvent(METTelemetryEventNames::ReadyForPricingEvent);

            break;

        case METSalesOrderProcessingStatus::PricingCompleted:

            METTelemetrySOPricingCompletedEvent telemetryPricingCompleted = METTelemetrySOPricingCompletedEvent::construct();
            telemetryPricingCompleted.addRunTimePropertyToAppinsights(_salesTable, _metSalesTable);

            telemetryPricingCompleted.processEvent(METTelemetryEventNames::PricingCompletedEvent);

            break;

        case METSalesOrderProcessingStatus::OptimisationCompleted:

            METTelemetrySOOptimisationCompletedEvent telemetryOptimisationCompleted = METTelemetrySOOptimisationCompletedEvent::construct();
            telemetryOptimisationCompleted.addRunTimePropertyToAppinsights(_salesTable, _metSalesTable);

            telemetryOptimisationCompleted.processEvent(METTelemetryEventNames::OptimizationCompletedEvent);

            break;

        case METSalesOrderProcessingStatus::ReadyForInvoicing:

            METTelemetrySOReadyForInvoicingEvent telemetryReadyForInvoicing = METTelemetrySOReadyForInvoicingEvent::construct();
            telemetryReadyForInvoicing.addRunTimePropertyToAppinsights(_salesTable, _metSalesTable);

            telemetryReadyForInvoicing.processEvent(METTelemetryEventNames::ReadyForInvoicingEvent);

            break;

        case METSalesOrderProcessingStatus::PendingProcessing:

            METTelemetrySOPendingProcessingEvent telemetryPendingProcessing = METTelemetrySOPendingProcessingEvent::construct();
            telemetryPendingProcessing.addRunTimePropertyToAppinsights(_salesTable, _metSalesTable);

            telemetryPendingProcessing.processEvent(METTelemetryEventNames::PendingProcessing);

            break;

        case METSalesOrderProcessingStatus::IOMSyncCompleted:

            METTelemetrySOIOMSyncCompletedEvent telemetryIOMSyncCompleted = METTelemetrySOIOMSyncCompletedEvent::construct();
            telemetryIOMSyncCompleted.addRunTimePropertyToAppinsights(_salesTable, _metSalesTable);

            telemetryIOMSyncCompleted.processEvent(METTelemetryEventNames::IOMSyncCompleted);

            break;
    }

}
